local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
------------------------------------------------------------------------
-- Floating quadrant terminal helpers
--
-- Shared grid: usable area (monitor minus reserved space, e.g. waybar)
-- split with symmetric outer/inner gaps so the four quadrant windows
-- line up whether you open one or all four.
------------------------------------------------------------------------
local quadGapOut = 16
local quadGapIn  = 10
local quadClass  = "kitty-quad" -- SUPER + SHIFT + Q: one quadrant, follows the cursor

-- Usable-area grid for a monitor, plus which half/quadrant a cursor pos falls in
local function usableGrid(mon, pos)
    local r = mon.reserved or { top = 0, bottom = 0, left = 0, right = 0 }
    local ux, uy = mon.x + r.left, mon.y + r.top
    local uw = mon.width  / mon.scale - r.left - r.right
    local uh = mon.height / mon.scale - r.top  - r.bottom

    local qw = (uw - 2 * quadGapOut - quadGapIn) / 2
    local qh = (uh - 2 * quadGapOut - quadGapIn) / 2
    local xL, xR = ux + quadGapOut, ux + quadGapOut + qw + quadGapIn
    local yT, yB = uy + quadGapOut, uy + quadGapOut + qh + quadGapIn

    local isLeft, isTop = true, true
    if pos then
        isLeft = (pos.x - ux) < uw / 2
        isTop  = (pos.y - uy) < uh / 2
    end

    return {
        ux = ux, uy = uy, uw = uw, uh = uh,
        qw = qw, qh = qh, xL = xL, xR = xR, yT = yT, yB = yB,
        isLeft = isLeft, isTop = isTop,
    }
end

-- The four top-level quadrant boxes for a monitor's usable-area grid
local function quadrantSlots(g)
    return {
        TL = { x = g.xL, y = g.yT, w = g.qw, h = g.qh },
        TR = { x = g.xR, y = g.yT, w = g.qw, h = g.qh },
        BL = { x = g.xL, y = g.yB, w = g.qw, h = g.qh },
        BR = { x = g.xR, y = g.yB, w = g.qw, h = g.qh },
    }
end

local function spawnInBox(cmd, class, box)
    hl.exec_cmd(cmd .. " --class " .. class, {
        float = true,
        move  = string.format("%d %d", math.floor(box.x), math.floor(box.y)),
        size  = string.format("%d %d", math.floor(box.w), math.floor(box.h)),
    })
end

-- resize first: Hyprland grows/shrinks floating windows from their
-- center, so moving afterwards is what actually lands them in place
local function placeActiveWindow(box)
    hl.dispatch(hl.dsp.window.resize({ x = math.floor(box.w), y = math.floor(box.h), relative = false }))
    hl.dispatch(hl.dsp.window.move({ x = math.floor(box.x), y = math.floor(box.y) }))
end

------------------------------------------------------------------------
-- SUPER + Q: open a terminal filling the quadrant under the cursor.
-- If the cursor is already over a SUPER + Q terminal (e.g. pressed again
-- without moving the mouse), that terminal's space is split in half
-- instead — the existing terminal keeps one half, the new one takes the
-- other. This recurses: pressing it again in the same spot splits again.
------------------------------------------------------------------------
local function boxesOverlap(a, b)
    return a.x < b.x + b.w and a.x + a.w > b.x and a.y < b.y + b.h and a.y + a.h > b.y
end

-- Any SUPER + Q terminal that overlaps the target quadrant already claims
-- it — pick the one closest to the cursor (handles the quadrant already
-- being split into halves, and small cursor drift landing in the gap
-- between them). Must be on the same workspace: floating windows keep
-- the same pixel coordinates across workspaces, so without this a
-- terminal left behind on another workspace would look like it's here.
local function findSplitTarget(pos, monId, wsId, quadrantBox)
    local best, bestDist
    for _, w in ipairs(hl.get_windows({ class = quadClass, floating = true })) do
        if w.monitor and w.monitor.id == monId and w.workspace and w.workspace.id == wsId then
            local wb = { x = w.at.x, y = w.at.y, w = w.size.x, h = w.size.y }
            if boxesOverlap(wb, quadrantBox) then
                local cx, cy = wb.x + wb.w / 2, wb.y + wb.h / 2
                local dist = (pos.x - cx) ^ 2 + (pos.y - cy) ^ 2
                if not best or dist < bestDist then
                    best, bestDist = w, dist
                end
            end
        end
    end
    return best
end

-- Targets a specific (possibly unfocused) window: dispatchers only ever
-- act on the focused window, so focus it first.
local function placeWindow(win, box)
    hl.dispatch(hl.dsp.focus({ window = win }))
    placeActiveWindow(box)
end

local function openQuadrantTerm()
    local pos = hl.get_cursor_pos()
    local mon = hl.get_monitor_at_cursor()
    if not pos or not mon or not mon.active_workspace then
        hl.exec_cmd(terminal)
        return
    end

    local g = usableGrid(mon, pos)
    local quadrantBox = {
        x = g.isLeft and g.xL or g.xR,
        y = g.isTop  and g.yT or g.yB,
        w = g.qw, h = g.qh,
    }

    local existing = findSplitTarget(pos, mon.id, mon.active_workspace.id, quadrantBox)
    if existing then
        local bx, by, bw, bh = existing.at.x, existing.at.y, existing.size.x, existing.size.y
        local box1, box2
        if bw >= bh then
            local halfw = (bw - quadGapIn) / 2
            box1 = { x = bx, y = by, w = halfw, h = bh }
            box2 = { x = bx + halfw + quadGapIn, y = by, w = halfw, h = bh }
        else
            local halfh = (bh - quadGapIn) / 2
            box1 = { x = bx, y = by, w = bw, h = halfh }
            box2 = { x = bx, y = by + halfh + quadGapIn, w = bw, h = halfh }
        end

        placeWindow(existing, box1)
        spawnInBox(terminal, quadClass, box2)
        return
    end

    spawnInBox(terminal, quadClass, quadrantBox)
end

hl.bind(mainMod .. " + Q", openQuadrantTerm)

------------------------------------------------------------------------
-- SUPER + SHIFT + Q: default Arch/Hyprland behavior, unchanged (tiled terminal)
------------------------------------------------------------------------
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.exec_cmd(terminal))

------------------------------------------------------------------------
-- SUPER + SPACE: if exactly one of the 4 quadrants (SUPER + Q terminals)
-- is empty, expand the focused quadrant terminal into it, provided the
-- empty quadrant shares an edge with it (same row or column). Pressing
-- SUPER + SPACE again on that now-expanded terminal shrinks it back to
-- its original quadrant.
------------------------------------------------------------------------
local function boxesMatch(a, b, tol)
    tol = tol or 20
    return math.abs(a.x - b.x) <= tol and math.abs(a.y - b.y) <= tol
       and math.abs(a.w - b.w) <= tol and math.abs(a.h - b.h) <= tol
end

local expandedFrom = {} -- window address -> { home = quadrant box, expanded = filled box }

local function fillEmptyQuadrant()
    local win = hl.get_active_window()
    if not win or win.class ~= quadClass or not win.monitor or not win.workspace then return end

    local winBox = { x = win.at.x, y = win.at.y, w = win.size.x, h = win.size.y }

    -- Already expanded from a previous SUPER + SPACE: shrink back home
    local prev = expandedFrom[win.address]
    if prev and boxesMatch(winBox, prev.expanded) then
        placeActiveWindow(prev.home)
        expandedFrom[win.address] = nil
        return
    end

    local g = usableGrid(win.monitor)
    local slots = quadrantSlots(g)

    local activeKey
    for key, box in pairs(slots) do
        if boxesMatch(box, winBox) then activeKey = key end
    end
    if not activeKey then return end

    -- A quadrant counts as occupied if ANY terminal overlaps it, not just
    -- one that exactly fills it — otherwise a quadrant split into halves
    -- (SUPER + Q pressed twice in the same spot) looks empty here.
    local occupied = { TL = false, TR = false, BL = false, BR = false }
    occupied[activeKey] = true
    for _, w in ipairs(hl.get_windows({ class = quadClass, floating = true })) do
        if w.address ~= win.address and w.monitor and w.monitor.id == win.monitor.id
           and w.workspace and w.workspace.id == win.workspace.id then
            local box = { x = w.at.x, y = w.at.y, w = w.size.x, h = w.size.y }
            for key, slot in pairs(slots) do
                if boxesOverlap(slot, box) then occupied[key] = true end
            end
        end
    end

    local emptyKey, emptyCount = nil, 0
    for key, filled in pairs(occupied) do
        if not filled then emptyKey = key; emptyCount = emptyCount + 1 end
    end
    if emptyCount ~= 1 then return end -- only handle the "exactly one gap" case

    local sameRow = (activeKey == "TL" and emptyKey == "TR") or (activeKey == "TR" and emptyKey == "TL")
                 or (activeKey == "BL" and emptyKey == "BR") or (activeKey == "BR" and emptyKey == "BL")
    local sameCol = (activeKey == "TL" and emptyKey == "BL") or (activeKey == "BL" and emptyKey == "TL")
                 or (activeKey == "TR" and emptyKey == "BR") or (activeKey == "BR" and emptyKey == "TR")

    local box
    if sameRow then
        box = { x = g.xL, y = slots[activeKey].y, w = g.uw - 2 * quadGapOut, h = g.qh }
    elseif sameCol then
        box = { x = slots[activeKey].x, y = g.yT, w = g.qw, h = g.uh - 2 * quadGapOut }
    else
        return -- diagonal gap: no single rectangle covers it cleanly
    end

    expandedFrom[win.address] = { home = slots[activeKey], expanded = box }
    placeActiveWindow(box)
end

hl.bind(mainMod .. " + SPACE", fillEmptyQuadrant)

------------------------------------------------------------------------
-- SUPER + ALT + SHIFT + arrow: explicitly expand the focused quadrant
-- terminal towards a specific neighbor (up/down = same column, left/right
-- = same row), instead of SUPER + SPACE's "only if exactly one quadrant
-- is empty" auto-detect. Only works if the target quadrant is empty.
-- SUPER + SPACE still shrinks the result back to its original quadrant.
------------------------------------------------------------------------
local expandNeighbor = {
    up    = { TL = false, TR = false, BL = "TL", BR = "TR" },
    down  = { TL = "BL",  TR = "BR",  BL = false, BR = false },
    left  = { TL = false, TR = "TL",  BL = false, BR = "BL" },
    right = { TL = "TR",  TR = false, BL = "BR",  BR = false },
}

local function expandTowards(direction)
    local win = hl.get_active_window()
    if not win or win.class ~= quadClass or not win.monitor or not win.workspace then return end

    local g = usableGrid(win.monitor)
    local slots = quadrantSlots(g)
    local winBox = { x = win.at.x, y = win.at.y, w = win.size.x, h = win.size.y }

    local activeKey
    for key, box in pairs(slots) do
        if boxesMatch(box, winBox) then activeKey = key end
    end
    if not activeKey then return end

    local targetKey = expandNeighbor[direction][activeKey]
    if not targetKey then return end -- already at that edge

    for _, w in ipairs(hl.get_windows({ class = quadClass, floating = true })) do
        if w.address ~= win.address and w.monitor and w.monitor.id == win.monitor.id
           and w.workspace and w.workspace.id == win.workspace.id then
            local box = { x = w.at.x, y = w.at.y, w = w.size.x, h = w.size.y }
            if boxesOverlap(slots[targetKey], box) then return end -- target occupied
        end
    end

    local box
    if direction == "left" or direction == "right" then
        box = { x = g.xL, y = slots[activeKey].y, w = g.uw - 2 * quadGapOut, h = g.qh }
    else
        box = { x = slots[activeKey].x, y = g.yT, w = g.qw, h = g.uh - 2 * quadGapOut }
    end

    expandedFrom[win.address] = { home = slots[activeKey], expanded = box }
    placeActiveWindow(box)
end

hl.bind(mainMod .. " + ALT + SHIFT + up",    function() expandTowards("up") end)
hl.bind(mainMod .. " + ALT + SHIFT + down",  function() expandTowards("down") end)
hl.bind(mainMod .. " + ALT + SHIFT + left",  function() expandTowards("left") end)
hl.bind(mainMod .. " + ALT + SHIFT + right", function() expandTowards("right") end)

-- vim-style aliases (H/J/K/L): same rollover issue as SUPER + SHIFT + right
hl.bind(mainMod .. " + ALT + SHIFT + K", function() expandTowards("up") end)
hl.bind(mainMod .. " + ALT + SHIFT + J", function() expandTowards("down") end)
hl.bind(mainMod .. " + ALT + SHIFT + H", function() expandTowards("left") end)
hl.bind(mainMod .. " + ALT + SHIFT + L", function() expandTowards("right") end)

