-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move/swap the active window with its neighbor in a direction.
-- For a floating window, "swap with the neighbor" doesn't make sense
-- (there's no tiling neighbor), and the direction dispatcher ends up
-- dragging it on top of the nearest window instead — so floating
-- windows get nudged by a fixed pixel step instead.
local function moveOrNudge(direction, dx, dy)
    return function()
        local win = hl.get_active_window()
        if win and win.floating then
            hl.dispatch(hl.dsp.window.move({ x = math.floor(win.at.x + dx), y = math.floor(win.at.y + dy) }))
        else
            hl.dispatch(hl.dsp.window.move({ direction = direction }))
        end
    end
end

local nudgeStep = 40
hl.bind(mainMod .. " + SHIFT + left",  moveOrNudge("l", -nudgeStep, 0))
hl.bind(mainMod .. " + SHIFT + right", moveOrNudge("r", nudgeStep, 0))
hl.bind(mainMod .. " + SHIFT + up",    moveOrNudge("u", 0, -nudgeStep))
hl.bind(mainMod .. " + SHIFT + down",  moveOrNudge("d", 0, nudgeStep))

-- vim-style aliases (H/J/K/L): SUPER + SHIFT + right seems to get lost on
-- this keyboard (likely rollover/ghosting on that specific key combo), so
-- these give a working fallback for all four directions.
hl.bind(mainMod .. " + SHIFT + H", moveOrNudge("l", -nudgeStep, 0))
hl.bind(mainMod .. " + SHIFT + L", moveOrNudge("r", nudgeStep, 0))
hl.bind(mainMod .. " + SHIFT + K", moveOrNudge("u", 0, -nudgeStep))
hl.bind(mainMod .. " + SHIFT + J", moveOrNudge("d", 0, nudgeStep))

-- Fullscreen (real) and maximize (keeps other windows behind)
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "maximized" }))

-- Cycle focus to the next window / swap active window with the next one
hl.bind(mainMod .. " + Tab",   hl.dsp.window.cycle_next({ next = true }))
hl.bind(mainMod .. " + grave", hl.dsp.window.swap({ next = true }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Move active window to the next/previous workspace and follow it there
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.move({ workspace = "+1", follow = true }))
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.move({ workspace = "-1", follow = true }))

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Resize the active window with the keyboard (works floating or tiled)
hl.bind(mainMod .. " + ALT + right", hl.dsp.window.resize({ x = 30,  y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + left",  hl.dsp.window.resize({ x = -30, y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + up",    hl.dsp.window.resize({ x = 0,   y = -30, relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + down",  hl.dsp.window.resize({ x = 0,   y = 30,  relative = true }), { repeating = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


